1	// args.mjs — minimal manual process.argv parser mirroring argparse's
2	// `--name value` form for the flags used by test20.
3	
4	const STRING_FLAGS = ['a', 'b', 'c', 'd', 'e'];
5	const INT_FLAGS = ['f', 'g'];
6	
7	export function parseArgs(argv = process.argv.slice(2)) {
8	  const values = {};
9	  for (let i = 0; i < argv.length; i++) {
10	    const tok = argv[i];
11	    if (!tok.startsWith('--')) {
12	      throw new Error(`unrecognized argument: ${tok}`);
13	    }
14	    const name = tok.slice(2);
15	    if (!STRING_FLAGS.includes(name) && !INT_FLAGS.includes(name)) {
16	      throw new Error(`unrecognized argument: --${name}`);
17	    }
18	    if (i + 1 >= argv.length) {
19	      throw new Error(`argument --${name}: expected one argument`);
20	    }
21	    const raw = argv[++i];
22	    if (INT_FLAGS.includes(name)) {
23	      const n = Number.parseInt(raw, 10);
24	      if (Number.isNaN(n) || String(n) !== raw.trim()) {
25	        throw new Error(`argument --${name}: invalid int value: ${raw}`);
26	      }
27	      values[name] = n;
28	    } else {
29	      values[name] = raw;
30	    }
31	  }
32	  for (const name of STRING_FLAGS.concat(INT_FLAGS)) {
33	    if (!(name in values)) {
34	      throw new Error(`the following arguments are required: --${name}`);
35	    }
36	  }
37	  return values;
38	}

1	// base58.mjs — pure-JS base58 (Bitcoin alphabet), matching PyPI base58.
2	
3	export const ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
4	const ALPHABET_BYTES = Array.from(ALPHABET, (c) => c.charCodeAt(0));
5	const INDEXES = new Map(ALPHABET_BYTES.map((b, i) => [b, i]));
6	
7	// bytes: number[] -> base58 ASCII codes (number[])
8	export function b58encode(bytes) {
9	  let zeros = 0;
10	  while (zeros < bytes.length && bytes[zeros] === 0) zeros++;
11	
12	  let n = 0n;
13	  for (const b of bytes) n = (n << 8n) | BigInt(b);
14	
15	  const digits = [];
16	  while (n > 0n) {
17	    const mod = Number(n % 58n);
18	    digits.push(ALPHABET_BYTES[mod]);
19	    n /= 58n;
20	  }
21	
22	  const one = ALPHABET_BYTES[0];
23	  const out = new Array(zeros).fill(one);
24	  for (let i = digits.length - 1; i >= 0; i--) out.push(digits[i]);
25	  return out;
26	}
27	
28	// str: base58 string -> decoded bytes (number[])
29	export function b58decode(str) {
30	  let n = 0n;
31	  for (const ch of str) {
32	    const code = ch.charCodeAt(0);
33	    const v = INDEXES.get(code);
34	    if (v === undefined) {
35	      throw new Error(`Invalid character ${JSON.stringify(ch)}`);
36	    }
37	    n = n * 58n + BigInt(v);
38	  }
39	
40	  const bytes = [];
41	  while (n > 0n) {
42	    bytes.push(Number(n & 0xffn));
43	    n >>= 8n;
44	  }
45	  bytes.reverse();
46	
47	  let zeros = 0;
48	  while (zeros < str.length && str[zeros] === '1') zeros++;
49	  return new Array(zeros).fill(0).concat(bytes);
50	}
51	
52	// n: non-negative integer (number or BigInt) -> base58 ASCII codes.
53	// PyPI: b58encode_int(0) == b'1'; no leading-zero padding.
54	export function b58encodeInt(n) {
55	  let v = BigInt(n);
56	  if (v === 0n) return [ALPHABET_BYTES[0]];
57	  const digits = [];
58	  while (v > 0n) {
59	    digits.push(ALPHABET_BYTES[Number(v % 58n)]);
60	    v /= 58n;
61	  }
62	  return digits.reverse();
63	}
64	
65	// str: base58 string -> integer (JS number).
66	export function b58decodeInt(str) {
67	  let n = 0;
68	  for (const ch of str) {
69	    const v = INDEXES.get(ch.charCodeAt(0));
70	    if (v === undefined) {
71	      throw new Error(`Invalid character ${JSON.stringify(ch)}`);
72	    }
73	    n = n * 58 + v;
74	  }
75	  return n;
76	}

